#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    // Operation (x,y): split into prefix[0..x-1], middle[x..n-y-1], suffix[n-y..n-1]
    // Result: suffix + middle + prefix
    auto apply_op = [&](int x, int y){
        vector<int> np;
        for(int i=n-y;i<n;i++) np.push_back(p[i]);
        for(int i=x;i<n-y;i++) np.push_back(p[i]);
        for(int i=0;i<x;i++) np.push_back(p[i]);
        p = np;
        ops.push_back({x,y});
    };

    for(int target = 0; target < n-1; target++){
        int pos = -1;
        for(int i = target; i < n; i++){
            if(p[i] == target+1){ pos = i; break; }
        }
        if(pos == target) continue;

        // Move element from pos to n-1
        if(pos != n-1){
            int x = pos + 1, y = 1;
            // need x+y <= n: pos+2 <= n, guaranteed since pos <= n-2
            apply_op(x, y);
        }

        // Now element is at position n-1. Move to target.
        if(target != n-1){
            int y = target + 1, x = 1;
            // need x+y <= n: target+2 <= n, guaranteed since target <= n-2
            apply_op(x, y);
        }
    }

    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
